import * as core from './joining-orders-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${label}</button>`;
const mark=(origin,n)=>Array.from({length:n},()=>`<span class="join-counter join-${origin}" data-join-counter data-origin="${origin}" aria-hidden="true"></span>`).join('');
const packet=(origin,n=10)=>`<span class="join-packet" role="img" aria-label="Ten counters: ${origin==='pip'?'Pip':'Dot'}'s ${n===10?'ten':n+' of ten'}">${mark(origin,n)}</span>`;
function mixedPacket(m){return `<span class="join-packet join-mixed" role="img" aria-label="New ten: ${m.newTenPip} Pip and ${m.newTenDot} Dot counters">${mark('pip',m.newTenPip)}${mark('dot',m.newTenDot)}</span>`;}
const bundleRow=(origin,n)=>Array.from({length:n},()=>packet(origin)).join('');
function sourceCard(name,count,ones,origin){return `<section class="join-source-card"><h3>${name}'s order: ${count}</h3><p>${count} individual seed counters: ${Math.floor(count/10)} ${Math.floor(count/10)===1?'ten':'tens'} and ${ones} ones.</p><div class="join-packets">${bundleRow(origin,Math.floor(count/10))}</div><div class="join-loose">${mark(origin,ones)}</div></section>`;}
function frame(m){const contents=mark('pip',m.framePip)+mark('dot',m.frameDot),empty=Array.from({length:10-m.framePip-m.frameDot},()=>'<span class="join-slot" aria-hidden="true"></span>').join('');return `<div class="join-frame" role="img" aria-label="Ten-frame: ${m.framePip} Pip and ${m.frameDot} Dot counters, ${10-m.framePip-m.frameDot} spaces empty">${contents}${empty}</div>`;}
function modelNote(m,s){
 if(!m.joined)return 'The orders are separate right now.';
 const inFrame=m.framePip+m.frameDot,newTen=m.newTenPip+m.newTenDot;
 if(newTen)return `The same ten ones are one new wrapped ten. One unwrapped one remains ${inFrame?'in the frame':'on the table'}.`;
 if(inFrame===10)return 'The full frame has ten unwrapped ones.';
 if(inFrame)return `The frame holds ${inFrame} unwrapped ones: ${m.framePip} from Pip and ${m.frameDot} from Dot.`;
 return s.id==='steady-orders'?'Three original tens and seven loose ones are together. Seven ones cannot make a new ten.':'Three original tens and eleven loose ones are together. Ten of those ones can become one new ten.';
}
function sourceModel(v){const s=v.source,m=v.model;if(!m.joined)return `<div class="join-source-cards">${sourceCard('Pip',s.pip,4,'pip')}${sourceCard('Dot',s.dot,s.dot%10,'dot')}</div><p id="join-model-note" role="status">${modelNote(m,s)}</p>`;
 return `<p class="join-source-strip">Pip's order: ${s.pip}. Dot's order: ${s.dot}. These same counters are on the joined table.</p><div class="join-table"><section><h3>Original wrapped tens</h3><div class="join-packets">${bundleRow('pip',2)}${bundleRow('dot',1)}</div></section>${m.newTenPip+m.newTenDot?`<section><h3>One new wrapped ten</h3><div class="join-packets">${mixedPacket(m)}</div></section>`:''}<section><h3>Loose counters</h3><p>${m.loosePip} from Pip, ${m.looseDot} from Dot.</p><div class="join-loose">${mark('pip',m.loosePip)}${mark('dot',m.looseDot)}</div></section><section><h3>Ten-frame</h3>${frame(m)}</section></div><p id="join-model-note" role="status">${modelNote(m,s)}</p>`;
}
function controls(v){
 const m=v.model,frameCount=m.framePip+m.frameDot,wrapCount=m.newTenPip+m.newTenDot;
 const reasons=[];
 if(m.joined){
  if(frameCount===10)reasons.push('The frame is full. Wrap these ten or return a counter before moving another.');
  else if(!wrapCount)reasons.push('Only a full frame of ten can be wrapped.');
  if(m.loosePip===0)reasons.push('No loose Pip counters remain to move.');
  if(m.looseDot===0)reasons.push('No loose Dot counters remain to move.');
  if(m.framePip===0)reasons.push('No Pip counter is in the frame to return.');
  if(m.frameDot===0)reasons.push('No Dot counter is in the frame to return.');
  if(!wrapCount)reasons.push('No new ten is ready to unwrap.');
  else if(!frameCount)reasons.push('The new ten is wrapped. You can unwrap it into the empty frame.');
  else if(frameCount)reasons.push('Return the remaining frame counter before unwrapping the new ten.');
 }
 return `<div class="join-actions" data-join-actions>${!m.joined?button('Join these orders','data-join-action="join"',true):`${button('Move one Pip counter to the frame',`data-join-action="move-pip" ${m.loosePip===0||frameCount===10?'disabled':''}`)}${button('Move one Dot counter to the frame',`data-join-action="move-dot" ${m.looseDot===0||frameCount===10?'disabled':''}`)}${button('Return one Pip counter from the frame',`data-join-action="return-pip" ${m.framePip===0?'disabled':''}`)}${button('Return one Dot counter from the frame',`data-join-action="return-dot" ${m.frameDot===0?'disabled':''}`)}${button('Wrap these ten',`data-join-action="wrap" ${frameCount!==10||wrapCount?'disabled':''}`,true)}${button('Unwrap the new ten',`data-join-action="unwrap" ${wrapCount!==10||frameCount?'disabled':''}`)}${button('Separate and start again','data-join-action="reset"')}`}</div><p class="tiny" id="join-action-hint">${reasons.join(' ')} Every move keeps Pip's ${v.source.pip} and Dot's ${v.source.dot} counters.</p><p id="join-action-notice" role="status" tabindex="-1"></p>`;
}
function feedback(h,model){if(!h)return '';return `<section class="join-feedback" id="join-feedback" role="status" tabindex="-1">${!coreModelEqual(h.model,model)?'<p>Earlier grouping: this check used the pictured arrangement saved when you checked.</p>':''}<p>${esc(h.feedbackText)}</p><p>${h.joined?'The pictured orders were joined.':'The pictured orders were still separate.'} ${h.regrouped?'One new ten was wrapped.':'No new ten was wrapped in this check.'}</p>${h.priorExposureUnknown?'<p>Earlier encounters or checks are unknown.</p>':''}</section>`;}
const modelSummary=m=>m.joined?`Original tens: 2 Pip and 1 Dot. Loose: ${m.loosePip} Pip and ${m.looseDot} Dot. Frame: ${m.framePip} Pip and ${m.frameDot} Dot. New ten: ${m.newTenPip} Pip and ${m.newTenDot} Dot.`:'Pip and Dot orders are separate; each still has its supplied tens and ones.';
function history(v){const w=v.work,k=w.kept;if(!k&&!w.history.length)return '<p>No draft or check is kept yet.</p>';return `<details class="join-history" data-join-history><summary>Saved work: ${k?'one kept draft':'no kept draft'}, ${w.history.length} ${w.history.length===1?'check':'checks'}</summary>${k?`<section data-join-kept><h3>Kept draft${!coreModelEqual(k.model,w.model)?' (earlier grouping)':''}</h3><p>${esc(k.source.request)}</p><p>${modelSummary(k.model)}</p><p>Proposed total: “${esc(k.raw)}”.</p>${k.latestCheck?`<p>Latest check when kept: ${esc(k.latestCheck.feedbackText)}</p>`:''}</section>`:''}${w.history.map(h=>`<section><h4>Check ${h.id}${!coreModelEqual(h.model,w.model)?' (earlier grouping)':''}</h4><p>${esc(h.source.request)}</p><p>${modelSummary(h.model)}</p><p>Proposed total: “${esc(h.raw)}”. ${esc(h.feedbackText)}</p></section>`).join('')}</details>`;}
const coreModelEqual=(a,b)=>Object.keys(a).every(k=>a[k]===b[k]);
function chooser(active){const cards=`<p>Each pair is open. The labels name Dot's ones; her whole order also has one ten.</p><div class="join-case-list">${core.joiningCases.map(c=>`<section class="join-case"><h3>${esc(c.title)}</h3><p>Pip: 24 (2 tens, 4 ones). Dot: ${c.dot} (1 ten, ${c.dot%10} ones).</p>${active===c.id?'<p>This order is open below.</p>':button('Start this order',`data-join-start="${c.id}"`)}</section>`).join('')}</div>`;return active?`<details class="join-chooser"><summary>Choose another pair of orders</summary>${cards}</details>`:`<section class="join-chooser"><h2>Choose a pair of orders</h2>${cards}</section>`;}
export function joiningOrdersEntry(){return `<section class="bundle-exchange-entry"><h2>Bundle Burrow: Joining Supply Orders</h2><p>Bring two pictured orders together. Sometimes ten ones can become one new ten.</p><a class="secondary" href="#numbers/join">Join supply orders</a></section>`;}
export function renderJoiningOrders(state){const v=core.joiningView(state);if(v.unsupported)return {facts:[],html:`<section class="joining-orders" data-join-root><h1>Joining Supply Orders</h1><p>This saved order uses an unfamiliar format, so it cannot be played here. The original is kept for export.</p>${button('Keep the original and start fresh','data-join-recover',true)}<a href="#numbers/exchange">Exchange Table</a></section>`};
 const head=`<section class="joining-orders" data-join-root><header class="join-head"><div><p>Bundle Burrow</p><h1>Joining Supply Orders</h1></div><a class="secondary" href="#numbers/exchange">Exchange Table</a></header><p>Join two imaginary seed-counter orders. You can keep any attempt and try both pairs.</p>`;
 if(v.absent)return {facts:[],html:head+chooser(null)+'</section>'};
 const w=v.work,s=v.source,help=w.helpOpen,example=w.exampleOpen,compare=w.history.length||w.kept;
 const capNotice=w.history.length===8?'<p class="join-cap-notice" role="note">The next check removes the oldest of eight saved checks from this order\'s local history. Download notes first if you want to keep it.</p>':'';
 const idNotice=w.nextCheckId>=Number.MAX_SAFE_INTEGER?'<p class="join-error" role="status">This order has reached its check limit. Your work is still kept.</p>':'';
 return {facts:[],html:head+chooser(s.id)+`<section class="join-work" id="join-work"><h2 id="join-work-title" tabindex="-1">${esc(s.title)}</h2><p class="join-request">${esc(s.request)}</p><p class="join-question">${s.pip} + ${s.dot} = ?</p><div data-join-model id="join-model" tabindex="-1">${sourceModel(v)}</div>${controls(v)}<form data-join-form><label for="join-total">Our proposed total, in individual counters</label><input id="join-total" data-join-total type="text" inputmode="numeric" maxlength="24" autocomplete="off" spellcheck="false" value="${esc(w.raw)}" aria-describedby="join-total-hint${w.error?' join-error':''}" ${w.error?'aria-invalid="true"':''}><p class="tiny" id="join-total-hint">Use digits from 0 to 99. Your draft stays yours until you check it.</p>${w.error?'<p class="join-error" id="join-error" role="alert" tabindex="-1">Enter a whole number from 0 to 99 using digits.</p>':''}${capNotice}${idNotice}<button class="primary" type="submit" data-join-check ${w.nextCheckId>=Number.MAX_SAFE_INTEGER?'disabled':''}>Check our total</button></form>${feedback(v.feedback,w.model)}<details class="join-help" ${help||example||w.support.includes('together')?'open':''}><summary>Some help, if you like</summary>${button('Show counting help','data-join-help')}${button('Show a separate example','data-join-example')}${button('We worked together',`data-join-together aria-pressed="${w.support.includes('together')}"`)}${hearButton(s.request,'Hear this order')}${help?'<p id="join-help-content" tabindex="-1">Count the tens from both orders. Then count the ones. If ten ones fill the frame, wrap those same ten as one more ten. The number of counters stays the same.</p>':''}${example?'<p id="join-example-content" tabindex="-1">Example: 12 and 18 join. Two tens and ten ones are on the table. Wrap those ten ones. Three tens and zero loose ones make 30.</p>':''}</details><section class="join-keep"><h3>Keep your work</h3>${button('Keep this draft','data-join-keep',true)}${w.kept?'<p id="join-kept-confirmation" tabindex="-1">A copy is kept in Saved work. Later changes need another Keep.</p>':''}${history(v)}</section>${compare?`<details class="join-compare"><summary>Talk together, if you like</summary><p>${s.id==='steady-orders'?"What changed when Pip's and Dot's orders joined? Did you need a new ten?":"If you wrapped ten ones, what stayed the same? How might the other pair of orders differ?"}</p></details>`:''}${v.priorExposureUnknown?'<p>Earlier encounters or checks are unknown after recovery.</p>':''}</section></section>`};
}
export function joiningOrdersNotes(state){if(!Object.hasOwn(state,'joiningOrders'))return '';const v=core.joiningView(state);if(v.unsupported)return `<details class="panel"><summary>Joining Supply Orders: saved work</summary><p>This original saved format cannot be played here. It is kept for export.</p><pre>${esc(JSON.stringify(v.raw,null,2))}</pre><a href="#numbers/join">Open Joining Supply Orders</a></details>`;return `<details class="panel"><summary>Joining Supply Orders: pictured joining and one entered total</summary><p>These records describe pictured practice, not an independent addition strategy, handwriting, fluency or mastery.</p>${Object.values(v.root.cases).map(w=>`<section><h3>${esc(w.source.title)}</h3><p>${w.history.length} retained checks. ${w.kept?'One draft kept.':'No draft kept.'}</p><pre>${esc(JSON.stringify(w,null,2))}</pre></section>`).join('')}${v.priorExposureUnknown?`<details><summary>Original recovered work</summary><pre>${esc(JSON.stringify(v.root.recovered,null,2))}</pre></details>`:''}<a href="#numbers/join">Open Joining Supply Orders</a></details>`;}
export function bindJoiningOrders(state,{save,render,navigate,focus}={}){
 const scope=document.querySelector('[data-join-root]');if(!scope)return;
 const current=core.joiningView(state),sourceId=current.source?.id;
 const still=()=>scope.isConnected&&core.joiningView(state).source?.id===sourceId;
 const act=(fn,target)=>{if(!still()||!fn())return false;save?.();render?.();focus?.(typeof target==='function'?target():target);return true;};
 scope.querySelectorAll('[data-join-start]').forEach(b=>b.onclick=()=>{if(!scope.isConnected||!core.startJoiningOrder(state,b.dataset.joinStart))return;save?.();render?.();focus?.('#join-work-title');});
 const actions={join:()=>core.joinOrders(state),'move-pip':()=>core.moveJoiningOne(state,'pip',true),'move-dot':()=>core.moveJoiningOne(state,'dot',true),'return-pip':()=>core.moveJoiningOne(state,'pip',false),'return-dot':()=>core.moveJoiningOne(state,'dot',false),wrap:()=>core.wrapJoiningTen(state),unwrap:()=>core.unwrapJoiningTen(state),reset:()=>core.resetJoiningModel(state)};
 scope.querySelectorAll('[data-join-action]').forEach(b=>b.onclick=()=>{const name=b.dataset.joinAction;if(!act(actions[name],()=>document.querySelector(`[data-join-action="${name}"]:not(:disabled)`)?`[data-join-action="${name}"]`:'#join-model'))return;if(name==='reset'){const notice=document.querySelector('#join-action-notice');if(notice){notice.textContent='The working grouping has been reset to two separate orders.';focus?.('#join-action-notice');}}});
 const input=scope.querySelector('[data-join-total]');input?.addEventListener('input',()=>{if(!still()||!core.setJoiningTotal(state,input.value))return;save?.();input.removeAttribute('aria-invalid');input.setAttribute('aria-describedby','join-total-hint');scope.querySelector('#join-error')?.remove();scope.querySelector('#join-feedback')?.remove();});
 scope.querySelector('[data-join-form]')?.addEventListener('submit',e=>{e.preventDefault();act(()=>core.checkJoiningTotal(state),()=>core.joiningView(state).work?.error?'#join-error':'#join-feedback');});
 scope.querySelector('[data-join-keep]')?.addEventListener('click',()=>act(()=>core.keepJoiningDraft(state),'#join-kept-confirmation'));
 scope.querySelector('[data-join-help]')?.addEventListener('click',()=>act(()=>core.openJoiningHelp(state,'help'),'#join-help-content'));
 scope.querySelector('[data-join-example]')?.addEventListener('click',()=>act(()=>core.openJoiningHelp(state,'example'),'#join-example-content'));
 scope.querySelector('[data-join-together]')?.addEventListener('click',()=>act(()=>core.useJoiningSupport(state,'together'),'[data-join-together]'));
 scope.querySelector('[data-join-recover]')?.addEventListener('click',()=>{if(!scope.isConnected||!core.recoverJoiningOrders(state))return;save?.();render?.();focus?.('#join-work-title');});
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(still()&&core.useJoiningSupport(state,'narrationRequested'))save?.();},{capture:true}));
}
